(()=>{'use strict';
const KEY='immobrain-viewing-timeline-v1',VIEWS='immobrain-viewings-v1',FAVORITES='immobrain-listing-status-v1',$=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const stages={none:'Keine Besichtigung',planned:'Besichtigung geplant',visited:'Besichtigung gemacht',offer:'Angebot gestellt',follow1:'Einmal nachgefasst',follow2:'Zweimal nachgefasst',follow3:'Dreimal nachgefasst',follow4:'Viermal nachgefasst'};
function read(key,fallback){try{return JSON.parse(localStorage.getItem(key))||fallback}catch{return fallback}}
function validDate(s){if(!/^\d{4}-\d{2}-\d{2}$/.test(s||''))return '';const d=new Date(s+'T00:00:00Z');return Number.isFinite(d.getTime())&&d.toISOString().slice(0,10)===s?s:''}
function today(){return new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Berlin',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date())}
function days(date,now=today()){return Math.round((new Date(now+'T00:00:00Z')-new Date(date+'T00:00:00Z'))/86400000)}
function displayDate(date){return validDate(date)?date.split('-').reverse().join('.'):'Kein Datum'}
function age(date){const n=days(date);return n<0?'in '+(-n)+' Tagen':n===0?'heute':'vor '+n+' Tagen'}
function info(item,record={},now=today()){const visits=[...item.visits.map(v=>validDate(v.date)),validDate(record.visit)].filter(Boolean).sort();const past=visits.filter(d=>d<=now),future=visits.filter(d=>d>now);const lastVisit=past.at(-1)||'',offer=validDate(record.offer),follows=Array.from({length:4},(_,i)=>validDate(record['follow'+(i+1)]));let stage=lastVisit?'visited':future.length?'planned':'none';if(offer&&offer<=now)stage='offer';for(let i=0;i<4;i++)if(follows[i]&&follows[i]<=now)stage='follow'+(i+1);const lastContact=[offer,...follows].filter(d=>d&&d<=now).sort().at(-1)||lastVisit;return {visits,lastVisit,future,offer,follows,stage,lastContact,next:validDate(record.next)}}
let items=[],records=read(KEY,{}),editing=null;const current=today();let month=new Date(current.slice(0,7)+'-01T12:00:00Z');
function gather(){const state=read(FAVORITES,{}),visits=read(VIEWS,[]),map=new Map(),aliases=new Map();for(const [key,v]of Object.entries(state)){if(!v?.favorite)continue;const x=v.snapshot||{},a={...x,...v.address},id='object:'+key;map.set(id,{id,key,name:[a.street,a.zipcode,a.city,x.title].filter(Boolean).join(' · ')||'Favorisiertes Objekt',visits:[]});aliases.set(key,id);for(const p of x.portalListings||[])aliases.set(p.local_key||JSON.stringify([String(p.source??''),String(p.immo_id??'')]),id)}for(const v of Array.isArray(visits)?visits:[]){if(!v?.id)continue;const key=v.data?.fields?.listingRef,id=key?(aliases.get(key)||'object:'+key):'viewing:'+v.id;if(!map.has(id))map.set(id,{id,key,name:v.name||'Besichtigung',visits:[]});map.get(id).visits.push({id:v.id,name:v.name,date:v.data?.fields?.date||''})}items=[...map.values()]}
function events(){const out=[];for(const x of items){const r=records[x.id]||{},i=info(x,r);for(const v of x.visits)if(validDate(v.date))out.push({date:v.date,label:'Besichtigung',item:x,cls:''});if(validDate(r.visit)&&!x.visits.some(v=>v.date===r.visit))out.push({date:r.visit,label:'Besichtigung (manuell)',item:x,cls:''});if(i.offer)out.push({date:i.offer,label:'Angebot',item:x,cls:'follow'});i.follows.forEach((d,n)=>{if(d)out.push({date:d,label:'Nachfassen '+(n+1),item:x,cls:'follow'})});if(i.next)out.push({date:i.next,label:'Kontakt geplant',item:x,cls:'next'})}return out}
function renderCalendar(){const year=month.getUTCFullYear(),m=month.getUTCMonth(),first=(month.getUTCDay()+6)%7,count=new Date(Date.UTC(year,m+1,0)).getUTCDate(),all=events();$('month-title').textContent=new Intl.DateTimeFormat('de-DE',{month:'long',year:'numeric',timeZone:'UTC'}).format(month);let html=['Mo','Di','Mi','Do','Fr','Sa','So'].map(d=>`<div class="weekday">${d}</div>`).join('')+'<div class="spacer"></div>'.repeat(first);for(let day=1;day<=count;day++){const date=year+'-'+String(m+1).padStart(2,'0')+'-'+String(day).padStart(2,'0');html+=`<div class="${date===today()?'today':''}"><strong>${day}</strong>${all.filter(e=>e.date===date).map(e=>`<a class="event ${e.cls}" href="#obj-${encodeURIComponent(e.item.id)}" title="${esc(e.item.name)}">${esc(e.label)} · ${esc(e.item.name)}</a>`).join('')}</div>`}$('calendar').innerHTML=html}
function render(){gather();renderCalendar();const filter=$('status-filter').value;$('objects').innerHTML=items.filter(x=>!filter||info(x,records[x.id]).stage===filter).map(x=>{const r=records[x.id]||{},i=info(x,r);return `<article class="object-timeline" id="obj-${encodeURIComponent(x.id)}"><h3>${esc(x.name)}</h3><span class="stage">${stages[i.stage]}</span><div class="timeline-list"><span>Besichtigt: ${i.lastVisit?displayDate(i.lastVisit)+' · '+age(i.lastVisit):'Noch keine Besichtigung'}</span>${i.future.length?`<span>Nächste Besichtigung: ${displayDate(i.future[0])} · ${age(i.future[0])}</span>`:''}${i.offer?`<span>Angebot: ${displayDate(i.offer)} · ${age(i.offer)}</span>`:''}${i.follows.map((d,n)=>d?`<span>${n+1}. Nachfassen: ${displayDate(d)} · ${age(d)}</span>`:'').join('')}</div>${i.next?`<p class="${days(i.next)>0?'overdue':''}">Nächster Kontakt: ${displayDate(i.next)} · ${days(i.next)>0?days(i.next)+' Tage überfällig':age(i.next)}</p>`:i.offer&&i.lastContact?`<p class="muted">Planungsvorschlag: nächster Kontakt 7 Tage nach dem letzten Kontakt. Individuell einstellbar.</p>`:''}${r.note?`<p>${esc(r.note)}</p>`:''}<div class="object-actions"><button type="button" data-edit="${esc(x.id)}">Termine / Status pflegen</button>${x.visits.map(v=>`<a href="/besichtigung.html?viewing=${encodeURIComponent(v.id)}">Checkliste ${esc(v.date?displayDate(v.date):v.name||'öffnen')} →</a>`).join('')}${x.key?`<a href="/besichtigung.html?listing=${encodeURIComponent(x.key)}">+ Besichtigung anlegen</a>`:''}</div></article>`}).join('')||'<p>Keine Objekte für diesen Status. Favorisiere ein Objekt oder speichere eine Besichtigung.</p>'}
$('follow-fields').innerHTML=Array.from({length:4},(_,i)=>`<label>${i+1}. Nachfassen am<input type="date" name="follow${i+1}"></label>`).join('');const form=$('timeline-form'),field=n=>form.elements.namedItem(n);
$('objects').onclick=e=>{const button=e.target.closest('[data-edit]');if(!button)return;editing=items.find(x=>x.id===button.dataset.edit);if(!editing)return;form.reset();const r=records[editing.id]||{};for(const name of ['visit','offer','follow1','follow2','follow3','follow4','next','note'])field(name).value=r[name]||'';$('edit-name').textContent=editing.name;$('edit-message').textContent='';for(const name of ['offer','follow1','follow2','follow3','follow4'])field(name).max=today();$('edit-dialog').showModal()};
$('close').onclick=()=>$('edit-dialog').close();$('suggest').onclick=()=>{const r=Object.fromEntries(new FormData(form)),i=info(editing,r),base=i.lastContact;if(!base){$('edit-message').textContent='Bitte zuerst eine Besichtigung oder ein Angebots-/Kontaktdatum eintragen.';return}const d=new Date(base+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+7);field('next').value=d.toISOString().slice(0,10);$('edit-message').textContent='Vorschlag übernommen. Du kannst das Datum frei ändern.'};
form.onsubmit=e=>{e.preventDefault();if(!editing||!form.reportValidity())return;const r=Object.fromEntries(new FormData(form));let prev=validDate(r.offer);for(let n=1;n<=4;n++){const d=validDate(r['follow'+n]);if(!d)continue;if(!prev){$('edit-message').textContent='Bitte ein Angebotsdatum und die vorherigen Nachfasskontakte eintragen.';return}if(d<prev){$('edit-message').textContent='Nachfasskontakte müssen in zeitlicher Reihenfolge nach dem Angebot liegen.';return}if(n>1&&!r['follow'+(n-1)]){$('edit-message').textContent='Bitte die vorherigen Nachfasskontakte ergänzen.';return}prev=d}const next={...read(KEY,{}),[editing.id]:r};try{localStorage.setItem(KEY,JSON.stringify(next));records=next;$('edit-dialog').close();$('message').textContent='Termine und Status gespeichert.';render()}catch{$('edit-message').textContent='Speicherung fehlgeschlagen. Bitte Browserspeicher prüfen.'}};
$('month-prev').onclick=()=>{month.setUTCMonth(month.getUTCMonth()-1);renderCalendar()};$('month-next').onclick=()=>{month.setUTCMonth(month.getUTCMonth()+1);renderCalendar()};$('status-filter').onchange=render;window.addEventListener('storage',e=>{if([KEY,VIEWS,FAVORITES].includes(e.key)||e.key===null){records=read(KEY,{});render()}});window.addEventListener('focus',render);let day=today();setInterval(()=>{if(today()!==day){day=today();render()}},60000);render();
})();
